<?php require 'config.php'; need();
$k=$_GET['kind']??'';$vid=(int)($_GET['visit']??0);$back=preg_match('/^[a-z_]+\.php$/',$_GET['back']??'')?$_GET['back']:'queue.php';
$s=$pdo->prepare('SELECT v.*,d.name dn FROM visits v LEFT JOIN departments d ON d.id=v.dept_id WHERE v.id=?');$s->execute([$vid]);$v=$s->fetch();if(!$v)die('Visit not found.');
$p=$pdo->prepare('SELECT * FROM patients WHERE id=?');$p->execute([$v['patient_id']]);$p=$p->fetch();
$q=function($sql)use($pdo,$vid){$s=$pdo->prepare($sql);$s->execute([$vid]);return $s->fetchAll();};
$t=['triage'=>'Triage receipt','consult'=>'Consultation receipt','lab'=>'Laboratory receipt','pharmacy'=>'Pharmacy dispensing receipt','imaging'=>'Imaging report receipt','procedure'=>'Procedure receipt'][$k]??die('Unknown receipt.');
echo doc_open($t,$p,$v);echo '<p>Reason for visit: <b>'.e($v['reason']?:'not recorded').'</b></p>';
if($k=='triage'){$r=$q('SELECT * FROM triage WHERE visit_id=?');$r=$r[0]??null;if($r){$b=($r['weight']&&$r['height'])?round($r['weight']/pow($r['height']/100,2),1):'-';echo '<table><tr><td>Temperature<td>'.e($r['temp']).'<td>Blood pressure<td>'.e($r['bp']).'<tr><td>Pulse<td>'.e($r['pulse']).'<td>Resp. rate<td>'.e($r['resp']).'<tr><td>SpO2<td>'.e($r['spo2']).'<td>Weight / height<td>'.e($r['weight']).' / '.e($r['height']).'<tr><td>BMI<td>'.$b.'<td>Time<td>'.e($r['created_at']).'</table><p>Complaint: '.e($r['complaint']).'</p>';}}
if($k=='consult'){$r=$q('SELECT c.*,u.name dr FROM consultations c LEFT JOIN users u ON u.id=c.doctor_id WHERE c.visit_id=?');if($r=$r[0]??null){echo '<p><b>Diagnosis:</b> '.e($r['diagnosis']).' '.e($r['icd10']).'</p><p><b>Plan:</b> '.nl2br(e($r['plan'])).'</p><p>Next step: '.e($r['outcome']).' | Doctor: '.e($r['dr']).'</p>';}
  echo '<table><tr><th>Lab tests ordered<th>Status';foreach($q('SELECT t.name,o.status FROM lab_orders o JOIN lab_tests t ON t.id=o.test_id WHERE o.visit_id=?') as $x)echo '<tr><td>'.e($x['name']).'<td>'.$x['status'];echo '</table><table><tr><th>Prescribed<th>Dose<th>Qty';foreach($q('SELECT d.name,x.dose,x.duration,x.qty FROM prescriptions x JOIN drugs d ON d.id=x.drug_id WHERE x.visit_id=?') as $x)echo '<tr><td>'.e($x['name']).'<td>'.e($x['dose'].' '.$x['duration']).'<td>'.$x['qty'];echo '</table>';}
if($k=='lab'){echo '<table><tr><th>Test<th>Result<th>Done';foreach($q("SELECT t.name,o.result,o.abnormal,o.done_at FROM lab_orders o JOIN lab_tests t ON t.id=o.test_id WHERE o.visit_id=? AND o.status='done'") as $x)echo '<tr><td>'.e($x['name']).'<td>'.e($x['result']).($x['abnormal']?' (ABNORMAL)':'').'<td>'.e($x['done_at']);echo '</table>';}
if($k=='pharmacy'){$tot=0;echo '<table><tr><th>Drug<th>Dose and duration<th>Qty<th class=r>KES';foreach($q("SELECT d.name,d.price,x.dose,x.duration,x.qty FROM prescriptions x JOIN drugs d ON d.id=x.drug_id WHERE x.visit_id=? AND x.status='dispensed'") as $x){$a=$x['qty']*$x['price'];$tot+=$a;echo '<tr><td>'.e($x['name']).'<td>'.e($x['dose'].' '.$x['duration']).'<td>'.$x['qty'].'<td class=r>'.number_format($a,2);}echo '<tr><th colspan=3>Total<th class=r>'.number_format($tot,2).'</table><p>Take the medicines exactly as written on the dose.</p>';}
if($k=='imaging')foreach($q("SELECT e.name,e.modality,o.findings,o.impression,o.reported_at,u.name rb FROM imaging_orders o JOIN imaging_exams e ON e.id=o.exam_id LEFT JOIN users u ON u.id=o.performed_by WHERE o.visit_id=? AND o.status='reported'") as $x)echo '<div class=box><b>'.e($x['name']).' ('.e($x['modality']).')</b><br>Findings: '.nl2br(e($x['findings'])).'<br><b>Impression:</b> '.nl2br(e($x['impression'])).'<br><small>Reported by '.e($x['rb']).' on '.e($x['reported_at']).'</small></div>';
if($k=='procedure')foreach($q("SELECT c.name,o.outcome,o.complications,o.done_at,u.name pb FROM procedure_orders o JOIN procedures_catalog c ON c.id=o.proc_id LEFT JOIN users u ON u.id=o.performed_by WHERE o.visit_id=? AND o.status='done'") as $x)echo '<div class=box><b>'.e($x['name']).'</b><br>Outcome: '.nl2br(e($x['outcome'])).'<br>Complications: '.e($x['complications']?:'none').'<br><small>Done by '.e($x['pb']).' on '.e($x['done_at']).'</small></div>';
echo doc_close($back);
